 const data={format:'document-compare.california-entities',version:1,source:{title:'Synthetic supported-limit QA; no official identity claim',authority:'Locally authored controlled QA',citation:'Synthetic capacity test, not official entity data',asOfDate:null,permissions:'Locally authored synthetic names authorized for local QA',rightsAttested:true},entries:Array.from({length:10000},(_,n)=>({name:'Department of Synthetic Capacity Review Services Unit '+key(n),category:'Synthetic QA',citation:'',annotation:'',checkEligible:true}))},raw=new TextEncoder().encode(JSON.stringify(data)),rawHash=hash(raw),beforeData=hash(JSON.stringify(data)),receipt=await prepareEntityAuthorityImport(raw,{inputFile:'synthetic-10000.json',importedAt:'2026-10-16T12:00:00.000Z'}),beforeReceipt=hash(JSON.stringify(receipt)),name=data.entries.at(-1).name,refs=Object.fromEntries(await Promise.all(['lcb','gpo'].map(async id=>[id,JSON.parse(await fs.readFile(new URL('../../app/data/'+id+'-reference.json',import.meta.url),'utf8'))]))),docs={matching:makeDocument(['The '+name.toLowerCase()+' shall act.'],'Current'),missing:makeDocument(['The Department of Unlisted Capacity Validation Services shall act.'],'Current'),head:makeDocument(['The director Jane Doe of the '+name+' shall act.'],'Current'),joint:makeDocument(['The '+name.toLowerCase()+' shall act. The director Jane Doe of the '+name+' shall act.'],'Current')},beforeDocs=hash(JSON.stringify(docs));
